-- =====================================================================
-- Baza de date MAGAZIN (exemplul 2, nivel mediu)
-- Un magazin online de materiale electrice: categorii, produse, clienți,
-- comenzi și produsele din fiecare comandă.
-- Motor: SQLite (se rulează în DBeaver: Execute SQL Script, Alt+X)
-- Relații: CATEGORII 1-N PRODUSE; CLIENTI 1-N COMENZI;
--          COMENZI N-M PRODUSE (prin tabelul de legătură DETALII_COMENZI)
-- Datele sunt fictive (nume, e-mailuri și telefoane generate).
-- =====================================================================

PRAGMA foreign_keys = ON;

DROP VIEW IF EXISTS v_vanzari;
DROP TABLE IF EXISTS detalii_comenzi;
DROP TABLE IF EXISTS comenzi;
DROP TABLE IF EXISTS clienti;
DROP TABLE IF EXISTS produse;
DROP TABLE IF EXISTS categorii;

CREATE TABLE categorii (
    id_categorie  INTEGER PRIMARY KEY,
    denumire      TEXT NOT NULL UNIQUE,
    descriere     TEXT
);

CREATE TABLE produse (
    id_produs     INTEGER PRIMARY KEY,
    denumire      TEXT    NOT NULL,
    id_categorie  INTEGER NOT NULL REFERENCES categorii(id_categorie),
    pret          REAL    NOT NULL CHECK (pret > 0),
    stoc          INTEGER NOT NULL DEFAULT 0 CHECK (stoc >= 0),
    cod_produs    TEXT    NOT NULL UNIQUE
);

CREATE TABLE clienti (
    id_client          INTEGER PRIMARY KEY,
    nume               TEXT NOT NULL,
    prenume            TEXT,
    tip_client         TEXT NOT NULL CHECK (tip_client IN ('persoană fizică', 'firmă')),
    email              TEXT NOT NULL UNIQUE,
    telefon            TEXT,
    judet              TEXT,
    oras               TEXT,
    data_inregistrare  TEXT
);

CREATE TABLE comenzi (
    id_comanda      INTEGER PRIMARY KEY,
    id_client       INTEGER NOT NULL REFERENCES clienti(id_client),
    data_comanda    TEXT    NOT NULL,
    status          TEXT    NOT NULL CHECK (status IN ('în curs', 'livrată', 'anulată')),
    modalitate_plata TEXT,
    data_livrare    TEXT
);

CREATE TABLE detalii_comenzi (
    id_detaliu    INTEGER PRIMARY KEY,
    id_comanda    INTEGER NOT NULL REFERENCES comenzi(id_comanda),
    id_produs     INTEGER NOT NULL REFERENCES produse(id_produs),
    cantitate     INTEGER NOT NULL CHECK (cantitate > 0),
    pret_unitar   REAL    NOT NULL,
    UNIQUE (id_comanda, id_produs)
);

